set local search_path = public, extensions;create extension if not exists pgtap with schema extensions;select plan(12);select has_table('public','learning_retrieval_schedules','Unified schedules exist');select has_column('public','learning_retrieval_schedules','target_type','Targets are polymorphic');select has_column('public','learning_retrieval_schedules','retrieval_mode','Recognition and production differ');select has_column('public','learning_retrieval_schedules','source_package_version_id','Package provenance remains');select has_column('public','learning_retrieval_schedules','lapse_count','Lapses drive repair');select has_column('public','learning_retrieval_schedules','exposure_count','Exposure limits exist');select has_table('public','indirect_retrieval_requests','Indirect requests exist');select has_table('public','retrieval_evidence_occurrences','Evidence ledger exists');select col_is_unique('public','retrieval_evidence_occurrences',array['student_id','schedule_id','occurrence_key'],'No double counting');select has_table('public','package_retrieval_policies','Package policy exists');select has_function('public','schedule_package_retrieval',array['uuid','uuid','timestamp with time zone'],'Completion schedules retrieval');select has_index('public','learning_retrieval_schedules','learning_retrieval_due_idx','Due queue indexed');select * from finish();rollback;
